// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        vm.prank(address(this), address(this));
        c = new PoCGame(address(this), 0);
    }

    function _test(uint256 amount1, uint256 amount2) internal {
        try c.AdjustBetAmounts(amount1) {} catch { return; }
        try c.AdjustBetAmounts(amount2) {} catch { return; }
        assertTrue(c.currentBetLimit() == amount2);
    }

    function testFuzz_test(uint256 amount1, uint256 amount2) public {
        _test(amount1, amount2);
    }

    receive() external payable {}
}
